import{_ as t,o as e,c as r,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"AI 如何使用知识库","description":"","frontmatter":{"title":"AI 如何使用知识库"},"headers":[],"relativePath":"knowledge/retrieval.md","filePath":"knowledge/retrieval.md","lastUpdated":1787949005000}'),i={name:"knowledge/retrieval.md"};function l(d,a,n,s,h,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="ai-如何使用知识库" tabindex="-1">AI 如何使用知识库 <a class="header-anchor" href="#ai-如何使用知识库" aria-label="Permalink to &quot;AI 如何使用知识库&quot;">​</a></h1><p>弄清 AI 拿知识库做什么，能帮你判断「内容该怎么写」和「答错了去哪查」。不需要技术背景，五分钟能看完。</p><h2 id="回答的过程" tabindex="-1">回答的过程 <a class="header-anchor" href="#回答的过程" aria-label="Permalink to &quot;回答的过程&quot;">​</a></h2><p>顾客发来一个问题后，AI 大致做三件事：</p><ol><li><strong>检索</strong>：从方案绑定的所有知识库里，找出和问题最相关的几条内容（知识项和商品资料都参与）。</li><li><strong>筛选</strong>：对找到的内容再排一次序，挑出真正可用的依据。</li><li><strong>组织回答</strong>：参考挑出的资料，按 AI 设置里的语气要求组织语言回复。</li></ol><p>所以 AI 的回答不是「原样背诵」知识库，而是<strong>参考资料后自己组织的</strong>。想让 AI 一字不差地发固定话术，用<a href="/aicare-docs/solution/keywords">关键词回复</a>。</p><h2 id="检索是语义级的" tabindex="-1">检索是语义级的 <a class="header-anchor" href="#检索是语义级的" aria-label="Permalink to &quot;检索是语义级的&quot;">​</a></h2><p>检索按含义匹配，不是按字面。顾客问「什么时候能到货」，即使知识条目写的是「发货时效」，也能命中。这也是为什么建议：</p><ul><li>问答的问题写顾客的自然问法，提高命中率。</li><li>一条只讲一件事，避免一条内容含多个主题时被稀释。</li></ul><h2 id="查看-ai-引用了什么" tabindex="-1">查看 AI 引用了什么 <a class="header-anchor" href="#查看-ai-引用了什么" aria-label="Permalink to &quot;查看 AI 引用了什么&quot;">​</a></h2><p>两处可以看到 AI 每次回答引用的资料：</p><ul><li><a href="/aicare-docs/solution/test">对话测试</a>的回复详情。</li><li><a href="/aicare-docs/workspace/records#会话详情">聊天记录</a>的会话详情。</li></ul><p>答错时先看引用：</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>引用了错误的条目</td><td>知识内容写得含糊或互相矛盾</td><td>修改或删掉冲突条目</td></tr><tr><td>没有引用任何资料</td><td>知识库缺这块内容</td><td>补充问答</td></tr><tr><td>引用正确但答得不好</td><td>话术组织问题</td><td>调整 AI 设置的回复要求</td></tr></tbody></table><h2 id="知识缺口" tabindex="-1">知识缺口 <a class="header-anchor" href="#知识缺口" aria-label="Permalink to &quot;知识缺口&quot;">​</a></h2><p>AI 遇到答不上来的问题会记录<strong>知识缺口</strong>，生成待办提醒你补充内容。请在客户端或网页工作台查看待办；绑定微信后，部分提醒也可以通过微信服务号推送。坚持每周处理缺口，知识库会越来越贴合你的真实客流。</p><h2 id="相关点数消耗" tabindex="-1">相关点数消耗 <a class="header-anchor" href="#相关点数消耗" aria-label="Permalink to &quot;相关点数消耗&quot;">​</a></h2><p>知识内容入库和检索会产生少量点数消耗，在账单里显示为「整理回答内容」和「挑选回答依据」。占比通常远小于 AI 回复本身，见<a href="/aicare-docs/billing/points">点数怎么计算</a>。</p>',18)])])}const _=t(i,[["render",l]]);export{u as __pageData,_ as default};
